PRAGMA foreign_keys=ON;
BEGIN;
CREATE TABLE "cases" ("system_id" TEXT PRIMARY KEY, "name" TEXT, "sector" TEXT, "jurisdiction" TEXT, "selection_rationale" TEXT, "change_in_understanding" TEXT, "coverage_limit" TEXT, "baseline_stage" TEXT, "independent_outcome_verified" INTEGER, "checked_date" TEXT, FOREIGN KEY("system_id") REFERENCES "system_keys"("system_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "documents" ("document_id" TEXT PRIMARY KEY, "label" TEXT, "title" TEXT, "issuing_body" TEXT, "document_date" TEXT, "date_text" TEXT, "date_precision" TEXT, "document_kind" TEXT, "source_role" TEXT, "url" TEXT, "scope" TEXT, "association_scope" TEXT, "review_depth" TEXT, "retrieval_basis" TEXT, "is_cached" INTEGER, "reviewed_text_sha256" TEXT, "checked_date" TEXT, "extraction_limit" TEXT, "snapshot" TEXT);
CREATE TABLE "observations" ("observation_id" TEXT PRIMARY KEY, "document_id" TEXT, "evidence_id" TEXT, "dimension" TEXT, "statement" TEXT, "claim_type" TEXT, "evidence_strength" TEXT, "event_date" TEXT, "date_basis" TEXT, "limitation" TEXT, "independent_outcome_verified" INTEGER, "current_version_match" TEXT, "checked_date" TEXT, FOREIGN KEY("document_id") REFERENCES "documents"("document_id") DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("evidence_id") REFERENCES "evidence"("evidence_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "case_observations" ("case_observation_id" TEXT PRIMARY KEY, "system_id" TEXT, "observation_id" TEXT, "link_basis" TEXT, "registry_assertion_ids" TEXT, FOREIGN KEY("system_id") REFERENCES "cases"("system_id") DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("observation_id") REFERENCES "observations"("observation_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "evidence" ("evidence_id" TEXT PRIMARY KEY, "document_id" TEXT, "observation_id" TEXT, "quote" TEXT, "locator" TEXT, "verification_mode" TEXT, "passage_match" INTEGER, "source_url" TEXT, FOREIGN KEY("document_id") REFERENCES "documents"("document_id") DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("observation_id") REFERENCES "observations"("observation_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "party_observations" ("party_observation_id" TEXT PRIMARY KEY, "observation_id" TEXT, "party_name_text" TEXT, "role_text" TEXT, "identity_resolution" TEXT, FOREIGN KEY("observation_id") REFERENCES "observations"("observation_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "financial_observations" ("financial_observation_id" TEXT PRIMARY KEY, "observation_id" TEXT, "amount_text" TEXT, "amount_kind" TEXT, "currency" TEXT, "actual_spending_verified" INTEGER, "aggregation_warning" TEXT, FOREIGN KEY("observation_id") REFERENCES "observations"("observation_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "coverage" ("coverage_id" TEXT PRIMARY KEY, "system_id" TEXT, "dimension" TEXT, "observation_ids" TEXT, "evidence_status" TEXT, "unknown_or_next_record" TEXT, "absence_interpretation" TEXT, FOREIGN KEY("system_id") REFERENCES "cases"("system_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "governance_links" ("governance_link_id" TEXT PRIMARY KEY, "system_id" TEXT, "instrument_id" TEXT, "existing_governance_link_id" TEXT, "link_type" TEXT, "rationale" TEXT, "implementation_observation_ids" TEXT, "instrument_evidence_ids" TEXT, "applicability_determination" TEXT, "compliance_verified" INTEGER, FOREIGN KEY("system_id") REFERENCES "cases"("system_id") DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("instrument_id") REFERENCES "governance_keys"("instrument_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "selection_decisions" ("selection_decision_id" TEXT PRIMARY KEY, "system_id" TEXT, "disposition" TEXT, "basis" TEXT, "search_design" TEXT, "counting_unit" TEXT, FOREIGN KEY("system_id") REFERENCES "system_keys"("system_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "system_keys" ("system_id" TEXT PRIMARY KEY, "name" TEXT, "sector" TEXT, "jurisdiction" TEXT, "owner_institution_id" TEXT);
CREATE TABLE "governance_keys" ("instrument_id" TEXT PRIMARY KEY, "title" TEXT, "document_status" TEXT, "primary_source_url" TEXT);
COMMIT;
